COMMIT;

-- DESTINO (50 registros)
COMMIT;

-- SEGURO (50 registros)
COMMIT;

-- CLIENTE (100 registros)
COMMIT;

-- EMPLEADO (50 registros)
COMMIT;

-- HOTEL (100 registros)
COMMIT;

-- TRANSPORTE (100 registros)
COMMIT;

-- PAQUETE (100 registros)
COMMIT;

-- RESERVA (150 registros)
COMMIT;

