COMMIT;

-- VERIFICACION DE CANTIDADES
SELECT 'ROL' AS TABLA, COUNT(*) AS TOTAL FROM ROL;
SELECT 'TELEFONO' AS TABLA, COUNT(*) AS TOTAL FROM TELEFONO;
SELECT 'DESTINO' AS TABLA, COUNT(*) AS TOTAL FROM DESTINO;
SELECT 'SEGURO' AS TABLA, COUNT(*) AS TOTAL FROM SEGURO;
SELECT 'CLIENTE' AS TABLA, COUNT(*) AS TOTAL FROM CLIENTE;
SELECT 'EMPLEADO' AS TABLA, COUNT(*) AS TOTAL FROM EMPLEADO;
SELECT 'HOTEL' AS TABLA, COUNT(*) AS TOTAL FROM HOTEL;
SELECT 'TRANSPORTE' AS TABLA, COUNT(*) AS TOTAL FROM TRANSPORTE;
SELECT 'PAQUETE' AS TABLA, COUNT(*) AS TOTAL FROM PAQUETE;
SELECT 'RESERVA' AS TABLA, COUNT(*) AS TOTAL FROM RESERVA;
SELECT 'PAGO' AS TABLA, COUNT(*) AS TOTAL FROM PAGO;

-- VALIDACION DE RELACIONES (deben devolver 0)
SELECT COUNT(*) AS RESERVAS_SIN_CLIENTE FROM RESERVA r LEFT JOIN CLIENTE c ON c.ID_CLIENTE=r.ID_CLIENTE WHERE c.ID_CLIENTE IS NULL;
SELECT COUNT(*) AS PAGOS_SIN_RESERVA FROM PAGO p LEFT JOIN RESERVA r ON r.ID_RESERVA=p.ID_RESERVA WHERE r.ID_RESERVA IS NULL;
SELECT COUNT(*) AS PAQUETES_SIN_DESTINO FROM PAQUETE p LEFT JOIN DESTINO d ON d.ID_DESTINO=p.ID_DESTINO WHERE d.ID_DESTINO IS NULL;
SELECT COUNT(*) AS RESERVAS_CON_TOTAL_INCORRECTO FROM RESERVA r JOIN PAQUETE p ON p.ID_PAQUETE=r.ID_PAQUETE WHERE r.TOTAL_PAGAR <> r.CANTIDAD_PERSONAS*p.PRECIO;
